class EventEmitter {
    Map<String, List<Consumer<Object>>> handlers = new HashMap<>();

    void on(String event, Consumer<Object> h) {
        handlers.computeIfAbsent(event, k -> new ArrayList<>()).add(h);
    }
    void emit(String event, Object data) {
        handlers.getOrDefault(event, List.of()).forEach(h -> h.accept(data));
    }
}

