class Tree<T extends Comparable<T>> {
    T wert;
    Tree<T> links, rechts;

    boolean enthält(T ziel) {
        int cmp = ziel.compareTo(wert);
        if (cmp == 0) return true;
        if (cmp < 0) return links != null && links.enthält(ziel);
        return rechts != null && rechts.enthält(ziel);
    }
}

