sealed interface Form permits Kreis, Rechteck, Dreieck { }
final class Kreis implements Form { double radius; }
final class Rechteck implements Form { double breite, hoehe; }
final class Dreieck implements Form { double basis, hoehe; }

double flaeche(Form f) {
    return switch (f) {
        case Kreis k -> Math.PI * k.radius * k.radius;
        case Rechteck r -> r.breite * r.hoehe;
        case Dreieck d -> 0.5 * d.basis * d.hoehe;
    };
}

