sealed interface Ausdruck permits Zahl, Plus, Mal { }
record Zahl(int wert) implements Ausdruck { }
record Plus(Ausdruck l, Ausdruck r) implements Ausdruck { }
record Mal(Ausdruck l, Ausdruck r) implements Ausdruck { }

int auswerten(Ausdruck e) {
    return switch (e) {
        case Zahl z -> z.wert();
        case Plus p -> auswerten(p.l()) + auswerten(p.r());
        case Mal m -> auswerten(m.l()) * auswerten(m.r());
    };
}

