sealed interface BinärBaum<T> permits Blatt, Knoten {}
record Blatt<T>() implements BinärBaum<T> {}
record Knoten<T>(T wert, BinärBaum<T> links, BinärBaum<T> rechts) implements BinärBaum<T> {}

static <T> int tiefe(BinärBaum<T> baum) {
    return switch (baum) {
        case Blatt<T> b -> 0;
        case Knoten<T> k -> 1 + Math.max(tiefe(k.links()), tiefe(k.rechts()));
    };
}

static <T> List<T> mergeSort(List<T> liste, Comparator<T> comp) {
    if (liste.size() <= 1) return liste;
    int mitte = liste.size() / 2;
    var links = mergeSort(liste.subList(0, mitte), comp);
    var rechts = mergeSort(liste.subList(mitte, liste.size()), comp);
    return merge(links, rechts, comp);
}

