record Zustand(int schritt, List<String> pfad) {}

List<String> bfs(Map<String, List<String>> graph, String start, String ziel) {
    Queue<Zustand> queue = new ArrayDeque<>();
    Set<String> besucht = new HashSet<>();
    queue.offer(new Zustand(0, List.of(start)));
    while (!queue.isEmpty()) {
        var z = queue.poll();
        var knoten = z.pfad().getLast();
        if (knoten.equals(ziel)) return z.pfad();
        if (besucht.add(knoten)) {
            graph.getOrDefault(knoten, List.of()).stream()
                .filter(n -> !besucht.contains(n))
                .forEach(n -> queue.offer(new Zustand(z.schritt()+1,
                    Stream.concat(z.pfad().stream(), Stream.of(n)).toList())));
        }
    }
    return List.of();
}

