    ImmutableList(List<T> quelle) {
        this.daten = quelle.toArray(); // defensive copy
    }

    @SuppressWarnings("unchecked")
    T get(int index) { return (T) daten[index]; }
    int size() { return daten.length; }
}

interface Cache<K, V> {
    Optional<V> get(K key);
    void put(K key, V value);
}

class ComputingCache<K, V> implements Cache<K, V> {
    private final Cache<K, V> backend;
    private final Function<K, V> loader;

    ComputingCache(Cache<K, V> backend, Function<K, V> loader) {
        this.backend = backend;
        this.loader = loader;
    }

    public Optional<V> get(K key) {
        return backend.get(key).or(() -> {
            V value = loader.apply(key);
            backend.put(key, value);
            return Optional.of(value);
        });
    }
}

